const items = $input.all();

const documentos = items
  .map((item) => ({
    contenido: item.json.document?.pageContent ?? '',
    metadata: item.json.document?.metadata ?? {},
    score: item.json.score ?? null,
  }))
  .filter((doc) => doc.contenido);

const contextoRag = documentos
  .map(
    (doc, index) =>
      `FRAGMENTO ${index + 1}:\n${doc.contenido}`
  )
  const vistos = new Set();

const documentosUnicos = documentos.filter((doc) => {
  const clave = doc.contenido
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();

  if (vistos.has(clave)) {
    return false;
  }

  vistos.add(clave);
  return true;
})
  .join('\n\n');

return [
  {
    json: {
      contexto_rag: contextoRag,
      referencias_rag: documentos.map((doc) => ({
        metadata: doc.metadata,
        score: doc.score,
      })),
    },
  },
];

const actividad = $('IA2 - Regeneración').first().json.output;
const evaluacionIA = $('IA3 - Reevaluación').first().json.output;

const rag =
  $('Unificar contexto RAG').first().json.contexto_rag ?? '';

// Texto completo de la actividad
const retos = Array.isArray(actividad.retos)
  ? actividad.retos
  : [];

const texto = [
  actividad.titulo ?? '',
  actividad.enunciado ?? '',
  actividad.objetivo ?? '',
  ...(actividad.conceptos_utilizados ?? []),
  actividad.contexto_personalizacion ?? '',
  actividad.personalizacion_aplicada?.interes_principal ?? '',
  actividad.personalizacion_aplicada?.tipo_integracion ?? '',
  actividad.personalizacion_aplicada?.escenario ?? '',
  actividad.personalizacion_aplicada?.papel_alumnado ?? '',
  ...retos.flatMap(reto => [
    reto.situacion ?? '',
    reto.pregunta ?? ''
  ]),
  actividad.cierre_narrativo ?? ''
]
  .join(' ')
  .toLowerCase();

const textoRag = String(rag).toLowerCase();

const violaciones = [];

// ---------------------------------------------------------
// 1. Explicaciones causales no respaldadas
// ---------------------------------------------------------

if (
  texto.includes('por qué range') ||
  texto.includes('por qué la función range')
) {
  violaciones.push(
    'Se solicita una explicación causal sobre range() que puede no estar respaldada explícitamente por el RAG.'
  );
}

// ---------------------------------------------------------
// 2. Conceptos no presentes en el material
// ---------------------------------------------------------

const expresionesControladas = [
  'límite de range',
  'límite superior',
  'valor superior',
  'off-by-one',
  'errores comunes'
];

for (const expresion of expresionesControladas) {
  if (
    texto.includes(expresion) &&
    !textoRag.includes(expresion)
  ) {
    violaciones.push(
      `Se introduce "${expresion}", que no aparece explícitamente en el RAG.`
    );
  }
}

// ---------------------------------------------------------
// 3. Detectar ejemplos numéricos de range()
// ---------------------------------------------------------

function extraerRangeNumericos(contenido) {
  return [
    ...String(contenido).matchAll(/range\s*\(\s*(\d+)\s*\)/gi)
  ].map(match => Number(match[1]));
}

const ejemplosPermitidos = new Set(
  extraerRangeNumericos(textoRag)
);

const ejemplosActividad = [
  ...new Set(extraerRangeNumericos(texto))
];

const ejemplosNoPermitidos = ejemplosActividad.filter(
  numero => !ejemplosPermitidos.has(numero)
);

if (ejemplosNoPermitidos.length > 0) {
  violaciones.push(
    `La actividad introduce ejemplos de range() no presentes explícitamente en el RAG: ${ejemplosNoPermitidos
      .map(numero => `range(${numero})`)
      .join(', ')}.`
  );
}

// ---------------------------------------------------------
// 3.1 Detectar cantidades asociadas a range() de forma indirecta
// ---------------------------------------------------------

const cantidadesNoPermitidas = new Set();

for (const reto of retos) {
  const textoReto = [
    reto.situacion ?? '',
    reto.pregunta ?? ''
  ]
    .join(' ')
    .toLowerCase();

  // Solo analizar cantidades si el reto hace referencia a range()
  if (/range\s*\(/i.test(textoReto)) {
    const cantidades = [
      ...textoReto.matchAll(
        /\b(\d+)\s*(vueltas?|repeticiones?|veces|iteraciones?)\b/gi
      )
    ].map(match => Number(match[1]));

    for (const numero of cantidades) {
      if (!ejemplosPermitidos.has(numero)) {
        cantidadesNoPermitidas.add(numero);
      }
    }
  }
}

if (cantidadesNoPermitidas.size > 0) {
  violaciones.push(
    `La actividad solicita utilizar range() con cantidades no respaldadas explícitamente por el RAG: ${[
      ...cantidadesNoPermitidas
    ]
      .map(numero => `${numero} repeticiones`)
      .join(', ')}.`
  );
}

// ---------------------------------------------------------
// 4. Generalización range(n)
// ---------------------------------------------------------

if (
  texto.includes('range(n)') &&
  !textoRag.includes('range(n)')
) {
  violaciones.push(
    'Se generaliza el ejemplo disponible a range(n), aunque esa regla no aparece explícitamente en el RAG.'
  );
}
// ---------------------------------------------------------
// 5. Detectar variantes de print() no presentes en el RAG
// ---------------------------------------------------------

function extraerPrints(contenido) {
  return [
    ...String(contenido).matchAll(/print\s*\(\s*([^)]*?)\s*\)/gi)
  ].map(match =>
    match[1]
      .trim()
      .replace(/\s+/g, ' ')
      .toLowerCase()
  );
}

const printsPermitidos = new Set(
  extraerPrints(textoRag)
);

const printsActividad = [
  ...new Set(extraerPrints(texto))
];

const printsNoPermitidos = printsActividad.filter(
  contenidoPrint => !printsPermitidos.has(contenidoPrint)
);

if (printsNoPermitidos.length > 0) {
  violaciones.push(
    `La actividad introduce usos de print() no presentes explícitamente en el RAG: ${printsNoPermitidos
      .map(valor => `print(${valor})`)
      .join(', ')}.`
  );
}

// ---------------------------------------------------------
// 6. Casos inversos o inferencias no respaldadas
// ---------------------------------------------------------

if (
  texto.includes('cuando no se conoce') ||
  texto.includes('si no se conoce')
) {
  if (
    !textoRag.includes('cuando no se conoce') &&
    !textoRag.includes('si no se conoce')
  ) {
    violaciones.push(
      'Se plantea un caso contrario que requiere una inferencia no explícita en el RAG.'
    );
  }
}

// ---------------------------------------------------------
// Resultado determinista
// ---------------------------------------------------------

const guardrailValido = violaciones.length === 0;

return {
  json: {
    evaluacion_ia: evaluacionIA,

    guardrail_determinista: {
      valido: guardrailValido,
      violaciones
    },

    valida_final:
      evaluacionIA.valida === true &&
      guardrailValido === true
  }
};

